(function ($) {
    'use strict';

    function loadPageChrome() {
        $.ajax({
            url: 'https://www.prisma.cat/ajax/mostrar_header_2.php',
            method: 'GET',
            dataType: 'html'
        }).done(function (page) {
            $('header').html(page);
        });

        $.ajax({
            url: 'https://www.prisma.cat/ajax/mostrar_footer_2.php',
            method: 'GET',
            dataType: 'html'
        }).done(function (page) {
            $('footer').html(page);
        });
    }

    function bindGiftPayment() {
        var submitting = false;

        $('#form_enviar_dades').on('click', function (event) {
            event.preventDefault();
            if (submitting) {
                return;
            }

            var form = document.getElementById('frm');
            if (!form) {
                $('#cnt-pagament').html(
                    '<h1>No podem iniciar el pagament</h1>' +
                    '<p>Actualitza la pàgina o contacta amb secretaria.</p>'
                );
                return;
            }

            submitting = true;
            $(this).attr('aria-disabled', 'true').addClass('boto-blau-disable');
            form.submit();
        });

        $('#form_cancelar_dades').on('click', function (event) {
            event.preventDefault();
            $('#cnt-pagament').html(
                '<h1>Pagament ajornat</h1>' +
                '<div class="d-flex flex-column tota-pagina">' +
                '<div class="container"><div class="row">' +
                '<div class="d-flex flex-column border-0 align-items-center w-100 mb-4">' +
                '<p>Pots reprendre el pagament des de l’enllaç segur de la teva comanda de regal.</p>' +
                '<p>Si necessites ajuda, contacta amb secretaria.</p>' +
                '</div></div></div></div>'
            );
        });
    }

    $(function () {
        loadPageChrome();
        bindGiftPayment();
    });
})(jQuery);
